import csv
import io

_DIGITS = set('0123456789')


def _parse_row(row, line_num):
    if row is None or row.get('sku') is None or row.get('name') is None or row.get('qty') is None:
        raise ValueError('line %d: missing field' % line_num)
    sku = row['sku'].strip()
    name = row['name'].strip()
    qty_raw = row['qty'].strip()
    if not sku:
        raise ValueError('line %d: empty sku' % line_num)
    if not name:
        raise ValueError('line %d: empty name' % line_num)
    if not qty_raw or not set(qty_raw) <= _DIGITS:
        raise ValueError('line %d: invalid qty' % line_num)
    return {'sku': sku, 'name': name, 'qty': int(qty_raw)}


def import_text(text, store, dry_run=False):
    rows = list(csv.DictReader(io.StringIO(text)))
    items = [_parse_row(row, i + 2) for i, row in enumerate(rows)]
    # Validate every row before committing anything:
    # compute the full plan against the starting state first.
    plan = [
        (item, store.get(item['sku']))
        for item in items
    ]
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item, before in plan:
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)
    return result

