class Store:
    def __init__(self, items=None):
        self.items = {k: v.copy() for k, v in (items or {}).items()}

    def get(self, sku):
        value = self.items.get(sku)
        return None if value is None else value.copy()

    def put(self, item):
        self.items[item['sku']] = item.copy()
